<script lang="ts">
 import {companion,updateData} from '../state.svelte';import {appearanceMode,displayTheme,periodAt} from '../theme';import {interfaceState} from '../interfaceState.svelte';import SquishSwitch from './SquishSwitch.svelte';import {chooseAppearance} from '../appearance.svelte';
 let night=$derived(displayTheme(appearanceMode(companion.data.preferences.appearanceMode,companion.data.preferences.theme),interfaceState.brightnessPreview??companion.data.preferences.brightness,interfaceState.now)==='night');
 let mode=$derived(appearanceMode(companion.data.preferences.appearanceMode,companion.data.preferences.theme));
 let period=$derived(periodAt(mode,interfaceState.brightnessPreview??companion.data.preferences.brightness,interfaceState.now));
 let panel:HTMLDivElement,button:HTMLButtonElement,open=$state(false),id=$props.id();
 function choose(value:boolean){chooseAppearance(value?'night':'day');}
 function select(value:'day'|'dusk'|'night'|'auto'){chooseAppearance(value);panel.hidePopover();button.focus({preventScroll:true});}
</script>
<div class="day-night-toggle"><SquishSwitch checked={night} label={night?'切换到白天模式':'切换到夜间模式'} reduced={companion.data.preferences.reduceMotion} onchange={choose}/><button bind:this={button} type="button" class="period-trigger" aria-label="选择场景时段" aria-expanded={open} popovertarget={id}><span>{period==='night'?'夜间':period==='dusk'?'傍晚':'白天'}</span><svg width="12" height="12" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="m4 6 4 4 4-4"/></svg></button><div bind:this={panel} id={id} popover="auto" tabindex="-1" role="dialog" aria-label="场景时段" class="period-popover" ontoggle={event=>open=event.newState==='open'}><strong>岛上的时光</strong><div>{#each [{id:'day',name:'白天'},{id:'dusk',name:'傍晚'},{id:'night',name:'夜间'},{id:'auto',name:'跟随时间'}] as option}<button type="button" aria-pressed={mode===option.id} class:chosen={mode===option.id} onclick={()=>select(option.id as 'day'|'dusk'|'night'|'auto')}>{option.name}</button>{/each}</div><p>自动：7:00 白天 · 16:00 傍晚 · 19:00 夜间</p></div></div>
<style>.day-night-toggle{display:flex;align-items:center;gap:5px;flex:none;color:var(--xy-ink)}.period-trigger{display:flex;align-items:center;gap:5px;min-height:40px;border:0;background:transparent;color:var(--xy-ink);font-size:12px;padding:4px 2px;cursor:pointer}.period-popover{position:fixed;inset:84px 24px auto auto;margin:0;width:320px;padding:18px;background:var(--xy-panel);color:var(--xy-ink);border:1px solid var(--xy-border);border-radius:12px;box-shadow:0 8px 24px #30296826}.period-popover strong{font-size:16px}.period-popover>div{display:flex;gap:6px;margin-top:12px;flex-wrap:wrap}.period-popover button{min-height:40px;padding:8px 11px;border:1px solid var(--xy-border);border-radius:8px;background:var(--xy-panel);color:var(--xy-ink);font-size:14px}.period-popover button.chosen{background:var(--xy-selected);border-color:var(--xy-accent)}.period-popover p{font-size:12px;color:var(--xy-secondary);line-height:1.8;margin-top:12px}</style>
